-- Module "shop", generated by SpecForge (admin-template@1) from "Shop".
-- Tables are created with PostgreSQL types derived from the mapping, prefixed "shop_" so they never
-- collide with the project's own; foreign keys come last, so the order of the tables does not matter.

create table shop_countries (
    code varchar(2) primary key,
    name varchar(80) not null
);

create table shop_customers (
    id bigint generated by default as identity primary key,
    version bigint not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    email varchar(120) not null,
    full_name varchar(100) not null,
    notes text,
    unique (email)
);

create table shop_orders (
    id bigint generated by default as identity primary key,
    version bigint not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    ordered_on date not null,
    status varchar(20) not null default 'NEW',
    customer_id bigint not null
);

create table shop_products (
    id bigint generated by default as identity primary key,
    version bigint not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    sku varchar(40) not null,
    name varchar(100) not null,
    price numeric(10, 2) not null,
    country_code varchar(2),
    unique (sku)
);

create table shop_tags (
    id bigint generated by default as identity primary key,
    version bigint not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    label varchar(40) not null,
    unique (label)
);

create table shop_product_tags (
    product_id bigint not null,
    tag_id bigint not null,
    primary key (product_id, tag_id)
);

alter table shop_orders add foreign key (customer_id) references shop_customers (id);
create index on shop_orders (customer_id);

alter table shop_products add foreign key (country_code) references shop_countries (code);
create index on shop_products (country_code);

alter table shop_product_tags add foreign key (product_id) references shop_products (id) on delete cascade;
alter table shop_product_tags add foreign key (tag_id) references shop_tags (id) on delete cascade;

-- Changing shop data needs this permission (security/Permissions.java must list it too, see
-- backend/specforge-shop.md). ADMIN holds every permission implicitly; other roles get it in the
-- Permissions screen.
insert into permission (code, area, position)
select 'shop.manage', 'SALES', coalesce(max(position), 0) + 10 from permission;
